/bin/bash -lc "python3 /workspace/tools.py resolve run://r-001 > /tmp/runtime_view.json
python3 - <<'PY'
import json
r=json.load(open('/tmp/runtime_view.json'))
print('TOP KEYS',list(r))
for k,v in r.items():
 if k not in ['context','study_schema']: print(k, json.dumps(v,ensure_ascii=False))
c=r['context'];print('CONTEXT KEYS',list(c))
for k,v in c.items():
 if k not in ['history','knowledge']:print(k,json.dumps(v,ensure_ascii=False))
print('HISTORY SUMMARY')
for t in c.get('history',[]):
 print(json.dumps({k:t.get(k) for k in ['id','parent','role','config','status','wall_seconds','parameters','train_seconds','error','note']},ensure_ascii=False), 'metrics', {k:t.get('validation',{}).get(k) for k in ['auc','logloss']},'diag',t.get('candidate_diagnostics'))
PY"

